mapper.select:
SELECT id, supplier_name AS supplierName, contact_person AS contactPerson, contact_phone AS contactPhone, email, address, business_license AS businessLicense, status, remark, create_time AS createTime, update_time AS updateTime FROM spd_supplier WHERE del_flag = #{delFlag}
AND supplier_name LIKE CONCAT('%', #{query.supplierName}, '%')
AND contact_person LIKE CONCAT('%', #{query.contactPerson}, '%')
AND status = #{query.status}
ORDER BY create_time DESC
